import java.util.*;

class Solution {
  public List<Integer> mostSimilar(int n, int[][] roads, String[] names, String[] targetPath) {
    List<List<Integer>> adj = new ArrayList<>();
    for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
    for (int[] r : roads) {
      adj.get(r[0]).add(r[1]);
      adj.get(r[1]).add(r[0]);
    }
    int m = targetPath.length;
    int[][] cost = new int[m][n], from = new int[m][n];
    for (int[] row : cost) Arrays.fill(row, Integer.MAX_VALUE);
    for (int v = 0; v < n; v++) cost[0][v] = names[v].equals(targetPath[0]) ? 0 : 1;
    for (int i = 1; i < m; i++)
      for (int v = 0; v < n; v++) {
        int mismatch = names[v].equals(targetPath[i]) ? 0 : 1;
        for (int u : adj.get(v))
          if (cost[i - 1][u] + mismatch < cost[i][v]) {
            cost[i][v] = cost[i - 1][u] + mismatch;
            from[i][v] = u;
          }
      }
    int end = 0;
    for (int v = 1; v < n; v++) if (cost[m - 1][v] < cost[m - 1][end]) end = v;
    LinkedList<Integer> path = new LinkedList<>();
    for (int i = m - 1, v = end; i >= 0; v = from[i][v], i--) path.addFirst(v);
    return path;
  }
}
